const $=id=>document.getElementById(id), money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults={mpg:6.5,driver:0,art:0,dispatch:0,factoring:0,target:1};
function read(k,f){try{return JSON.parse(localStorage.getItem(k))||f}catch{return f}}let profile={...defaults,...read('sagi-profile',{})},saved=read('sagi-trips',[]),last=null;
function persist(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{toast('Storage unavailable. Export your estimate before leaving.');return false}}
function toast(s){$('toast').textContent=s;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3500)}
function tab(id){document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!==id);document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===id));if(id==='saved')renderSaved();if(id==='dashboard')renderDashboard();if(id==='business')renderBusiness();if(id==='connections'&&window.renderFuel)window.renderFuel();if(id==='ratecons'&&window.renderRatecons)window.renderRatecons();window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>tab(b.dataset.go));
const fields=[['mpg','Fuel economy (miles / US gallon)',0.1],['driver','Driver pay ($/mile)',0],['art','SST/ART (%)',0],['dispatch','Dispatch (%)',0],['factoring','Factoring (%)',0]];
$('settingFields').innerHTML=fields.map(([id,label,min])=>`<label>${label}<input id="s_${id}" type="number" min="${min}" step="0.01" value="${profile[id]}" required></label>`).join('');
$('settingsForm').onsubmit=e=>{e.preventDefault();const p={...profile};fields.forEach(([id])=>p[id]=Number($('s_'+id).value));if(p.art+p.dispatch+p.factoring>=100){toast('Combined deductions must be below 100%.');return}if(persist('sagi-profile',p)){profile=p;$('settingsStatus').textContent='Saved on this device.';if(last)calculate()}};
const tripNumbers=['pay','miles','deadhead','days','price','tolls','scale','reefer','parking','defGallons','defCost','target'];
const tripText=['origin','destination','loadNumber','pickupAt','deliveryAt','pickupAddress','deliveryAddress','broker','equipment','weight','notes'];
function tripMath(t,p){return TripCore.estimate(t,p)}
function calculate(){if(!$('tripForm').checkValidity()){last=null;$('result').innerHTML='<h2>Finish your trip details.</h2><p>Enter valid values to update this estimate.</p>';return}const t={};tripText.forEach(k=>t[k]=$(k).value.trim());tripNumbers.forEach(k=>t[k]=Number($(k).value));t.lumper=$('lumper').value===''?null:Number($('lumper').value);t.lumperPayer=$('lumperPayer').value;t.lumperDeduct=$('lumperDeduct').checked;let r;try{r=tripMath(t,profile)}catch(e){last=null;$('result').innerHTML='<h2>Check your numbers.</h2><p>'+esc(e.message)+'</p>';return}last={...t,...r,loadedMiles:t.miles,profile:{...profile},date:new Date().toISOString(),version:2};const rows=[['Diesel · '+r.gallons.toFixed(1)+' gal',r.fuel],['Driver pay',r.driver],['SST/ART + dispatch + factoring',r.deductions],['Tolls',t.tolls],['Weight scale',t.scale],['Reefer fuel',t.reefer],['Parking',t.parking],['DEF · '+t.defGallons+' gal',t.defCost],['Lumper deducted',r.lumperCharge]];
$('result').innerHTML=`<span class="eyebrow">ESTIMATED EARNINGS THIS TRIP</span><div class="amount">${money(r.net)}</div><small>From ${money(t.pay)} in load pay</small><div class="metrics"><div><b>${money(r.cost)}</b><small>Estimated trip expenses</small></div><div><b>${money(r.netMile)}</b><small>Earnings / all miles</small></div></div>${r.lumperPending?'<p class="note"><b>Lumper cost or payer is pending.</b>It is excluded from this estimate. Update after delivery.</p>':`<p class="hint">Lumper: ${esc(t.lumperPayer)} · recorded ${money(t.lumper||0)}${t.lumperDeduct?'':' · not deducted'}</p>`}<div class="breakdown">${rows.map(([label,v])=>`<div class="row"><span>${label}</span><b>${money(v)}</b></div>`).join('')}</div><div class="goal"><b>${r.netMile>=t.target?'Meets your earnings target':'Below your earnings target'}</b><br>Ask for at least ${money(Math.ceil((r.targetRate-1e-9)*100)/100)} to keep ${money(t.target)}/mile.<br><small>Break-even load pay: ${money(Math.ceil((r.breakEven-1e-9)*100)/100)} · ${r.miles.toLocaleString()} total miles</small></div><p>Based on entered costs. Recurring business costs are shown separately on the weekly dashboard. Unentered costs and IFTA settlement are excluded.</p><button id="saveTrip">Save this estimate</button>`;$('saveTrip').onclick=()=>{const next=[{...last,id:crypto.randomUUID(),rateconId:window.activeRateconId||null},...saved];if(persist('sagi-trips',next)){saved=next;toast('Estimate saved. Add final costs after delivery.')}};}
$('tripForm').onsubmit=e=>{e.preventDefault();calculate();if(innerWidth<790)$('result').scrollIntoView({behavior:'smooth',block:'center'})};$('tripForm').oninput=()=>{if(last)calculate()};
$('lumperPayer').onchange=()=>{const payer=$('lumperPayer').value;$('lumperDeduct').checked=payer==='driver';if(payer==='none')$('lumper').value='0';if(last)calculate()};
$('example').onclick=()=>{$('tripForm').reset();window.setActiveRatecon?.(null);Object.entries({origin:'Crossville, TN',destination:'Lakeland, FL',pay:2200,miles:700,deadhead:50,days:2,price:3.50,tolls:25,scale:20}).forEach(([k,v])=>$(k).value=v);calculate();toast('Sample load loaded. Review your assumptions.');};
